import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { int n = Integer.parseInt(br.readLine()); long[] a = new long[n]; StringTokenizer st = new StringTokenizer(br.readLine()); for (int i = 0; i < n; i++) { a[i] = Long.parseLong(st.nextToken()); } int[] dp = new int[n]; dp[n - 1] = 1; for (int i = n - 2; i >= 0; i--) { if ((a[i] > 0 && a[i + 1] < 0) || (a[i] < 0 && a[i + 1] > 0)) { dp[i] = dp[i + 1] + 1; } else { dp[i] = 1; } } StringBuilder sb = new StringBuilder(); for (int i = 0; i < n; i++) { sb.append(dp[i]).append(i == n - 1 ? "" : " "); } out.println(sb.toString()); } out.flush(); out.close(); } }